mapper.select:
SELECT m.`perms` FROM sys_menu m LEFT JOIN sys_role_menu rm ON rm.menu_id = m.id LEFT JOIN sys_role r ON r.id = rm.role_id LEFT JOIN sys_user_role ur ON ur.role_id = r.id LEFT JOIN sys_user u ON u.id = ur.user_id
m.`perms` IS NOT NULL AND m.`perms` <> '' AND u.`status` = 0 AND r.`status` = 0 AND m.`status` = 0
AND u.id = #{userId}
